@props([
    'name' => null,
    'value' => [],
    'placeholder' => null,
    'max' => null,
    'invalid' => false,
    'disabled' => false,
    'size' => null,
])

@aware([
    'fieldInvalid' => false,
    'controlId' => null,
])

@php
    use Illuminate\Support\Arr;
    use Illuminate\Support\Str;

    if (! filled($name)) {
        throw new \InvalidArgumentException('The pillbox component requires a [name] attribute.');
    }

    $invalid = $invalid || $fieldInvalid;

    $resolvedControlId = $attributes->get('id')
        ?? $controlId
        ?? $name;

    $fieldName = Str::endsWith($name, '[]') ? $name : $name.'[]';

    $normalizedValue = collect(Arr::wrap($value))
        ->filter(fn ($item) => filled($item))
        ->map(fn ($item) => (string) $item)
        ->values()
        ->all();

    $resolvedPlaceholder = filled($placeholder)
        ? $placeholder
        : __('stencil-ui::messages.pillbox_placeholder');

    $rootClasses = collect([
        'pillbox flex min-w-0 flex-col gap-2',
        'w-full' => ! filled($attributes->get('class')),
    ])->filter()->implode(' ');

    $rootAttributes = $attributes
        ->except(['name', 'value', 'placeholder', 'max', 'invalid', 'disabled', 'size', 'id'])
        ->class($rootClasses)
        ->merge([
            'data-pillbox' => true,
            'data-pillbox-name' => $fieldName,
            'data-pillbox-value' => json_encode($normalizedValue, JSON_THROW_ON_ERROR),
        ]);

    if ($max !== null) {
        $rootAttributes = $rootAttributes->merge([
            'data-pillbox-max' => max(1, (int) $max),
        ]);
    }

    if ($disabled) {
        $rootAttributes = $rootAttributes->merge(['data-disabled' => 'true']);
    }

    if ($invalid) {
        $rootAttributes = $rootAttributes->merge([
            'data-invalid' => 'true',
            'aria-invalid' => 'true',
        ]);
    }

    $chipSizeClasses = $size === 'sm'
        ? 'text-xs px-1.5 py-0'
        : 'text-xs px-2 py-0.5';

    $chipClasses = collect([
        'pillbox__chip',
        'inline-flex max-w-full items-center gap-1 rounded-md border border-zinc-200 bg-zinc-50 font-medium text-zinc-700',
        'dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-200',
        $chipSizeClasses,
    ])->implode(' ');

    $chipRemoveClasses = collect([
        'pillbox__chip-remove',
        'inline-flex shrink-0 items-center justify-center rounded-sm text-zinc-500 hover:text-zinc-900',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-950/10',
        'dark:text-zinc-400 dark:hover:text-zinc-50 dark:focus-visible:ring-zinc-300/20',
        $size === 'sm' ? 'size-3.5' : 'size-4',
    ])->implode(' ');
@endphp

<div {{ $rootAttributes }}>
    <div
        class="pillbox__field flex min-w-0 flex-wrap items-center gap-1 rounded-md border border-zinc-200 bg-white px-2 py-1.5 shadow-sm focus-within:ring-2 focus-within:ring-zinc-950/10 dark:border-zinc-800 dark:bg-zinc-950 dark:focus-within:ring-zinc-300/20 {{ $invalid ? 'border-red-500 dark:border-red-500' : '' }}"
        data-pillbox-field
    >
        <div class="pillbox__list flex min-w-0 flex-wrap items-center gap-1" data-pillbox-list></div>

        <input
            type="text"
            class="pillbox__input min-w-[8rem] flex-1 border-0 bg-transparent p-0 text-sm text-zinc-900 placeholder:text-zinc-500 focus:ring-0 focus:outline-none dark:text-zinc-50 dark:placeholder:text-zinc-400"
            data-pillbox-input
            placeholder="{{ $resolvedPlaceholder }}"
            autocomplete="off"
            @if (filled($resolvedControlId)) id="{{ $resolvedControlId }}" @endif
            @if ($disabled) disabled @endif
            @if ($invalid) aria-invalid="true" @endif
        />
    </div>

    <div data-pillbox-hidden-inputs data-pillbox-field-name="{{ $fieldName }}">
        @foreach ($normalizedValue as $tag)
            <input type="hidden" name="{{ $fieldName }}" value="{{ $tag }}" data-pillbox-hidden-input />
        @endforeach
    </div>

    <template data-pillbox-chip-template>
        <span class="{{ $chipClasses }}" data-pillbox-chip>
            <span class="min-w-0 truncate" data-pillbox-chip-label></span>
            <button
                type="button"
                class="{{ $chipRemoveClasses }}"
                data-pillbox-chip-remove
                aria-label="{{ __('stencil-ui::messages.pillbox_remove') }}"
            >
                <x-ui::icon name="x" class="{{ $size === 'sm' ? 'size-3' : 'size-3.5' }}" />
            </button>
        </span>
    </template>
</div>

/**
 * Stencil — pillbox / tags input (vanilla JS, no Alpine).
 */

const PILLBOX_SELECTOR = '[data-pillbox]';
const initialized = new WeakSet();

/**
 * @param {ParentNode} root
 */
export function initPillboxes(root = document) {
    root.querySelectorAll(PILLBOX_SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLElement)) {
            return;
        }

        if (initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindPillbox(element);
    });
}

/**
 * @param {HTMLElement} root
 */
function bindPillbox(root) {
    const list = root.querySelector('[data-pillbox-list]');
    /** @type {HTMLInputElement | null} */
    const textInput = root.querySelector('[data-pillbox-input]');
    const hiddenContainer = root.querySelector('[data-pillbox-hidden-inputs]');
    /** @type {HTMLTemplateElement | null} */
    const chipTemplate = root.querySelector('template[data-pillbox-chip-template]');
    const fieldName = root.getAttribute('data-pillbox-name') ?? '';
    const maxAttr = root.getAttribute('data-pillbox-max');
    const max = maxAttr !== null && maxAttr !== '' ? Number.parseInt(maxAttr, 10) : null;
    const disabled = root.hasAttribute('data-disabled');

    /** @type {string[]} */
    let tags = [];

    try {
        const parsed = JSON.parse(root.getAttribute('data-pillbox-value') ?? '[]');

        if (Array.isArray(parsed)) {
            tags = parsed.map(String).filter((tag) => tag.trim() !== '');
        }
    } catch {
        tags = [];
    }

    if (
        !(list instanceof HTMLElement) ||
        !(textInput instanceof HTMLInputElement) ||
        !(hiddenContainer instanceof HTMLElement) ||
        !(chipTemplate instanceof HTMLTemplateElement) ||
        fieldName === ''
    ) {
        return;
    }

    /**
     * @param {HTMLElement} target
     */
    function dispatchChange(target) {
        target.dispatchEvent(new Event('input', { bubbles: true }));
        target.dispatchEvent(new Event('change', { bubbles: true }));
    }

    /**
     * @returns {string[]}
     */
    function getTags() {
        return [...tags];
    }

    /**
     * @param {string[]} values
     */
    function setTags(values) {
        const unique = [];

        values.forEach((value) => {
            const trimmed = value.trim();

            if (trimmed === '' || unique.includes(trimmed)) {
                return;
            }

            unique.push(trimmed);
        });

        if (max !== null && unique.length > max) {
            unique.length = max;
        }

        tags = unique;
        render();
        dispatchChange(root);
    }

    function renderChips() {
        list.replaceChildren();

        tags.forEach((tag, index) => {
            const fragment = chipTemplate.content.cloneNode(true);
            const chip =
                fragment instanceof DocumentFragment
                    ? fragment.querySelector('[data-pillbox-chip]')
                    : null;

            if (!(chip instanceof HTMLElement)) {
                return;
            }

            const label = chip.querySelector('[data-pillbox-chip-label]');

            if (label instanceof HTMLElement) {
                label.textContent = tag;
            }

            const removeButton = chip.querySelector('[data-pillbox-chip-remove]');

            if (removeButton instanceof HTMLButtonElement) {
                removeButton.disabled = disabled;
                removeButton.addEventListener('click', (event) => {
                    event.preventDefault();

                    if (disabled) {
                        return;
                    }

                    const next = getTags();
                    next.splice(index, 1);
                    setTags(next);
                    textInput.focus();
                });
            }

            list.appendChild(fragment);
        });
    }

    function renderHiddenInputs() {
        hiddenContainer.replaceChildren();

        tags.forEach((tag) => {
            const input = document.createElement('input');
            input.type = 'hidden';
            input.name = fieldName;
            input.value = tag;
            input.setAttribute('data-pillbox-hidden-input', '');
            hiddenContainer.appendChild(input);
        });
    }

    function render() {
        renderChips();
        renderHiddenInputs();

        const atMax = max !== null && tags.length >= max;
        textInput.disabled = disabled || atMax;
        textInput.placeholder =
            atMax && max !== null
                ? ''
                : (textInput.getAttribute('data-original-placeholder') ?? textInput.placeholder);
    }

    /**
     * @param {string} raw
     */
    function addFromInput(raw) {
        const parts = raw
            .split(',')
            .map((part) => part.trim())
            .filter((part) => part !== '');

        if (parts.length === 0) {
            return;
        }

        setTags([...getTags(), ...parts]);
        textInput.value = '';
    }

    textInput.setAttribute('data-original-placeholder', textInput.placeholder);

    textInput.addEventListener('keydown', (event) => {
        if (disabled) {
            return;
        }

        if (event.key === 'Enter' || event.key === ',') {
            event.preventDefault();

            if (textInput.value.trim() !== '') {
                addFromInput(textInput.value);
            }

            return;
        }

        if (event.key === 'Backspace' && textInput.value === '' && tags.length > 0) {
            event.preventDefault();
            const next = getTags();
            next.pop();
            setTags(next);
        }
    });

    textInput.addEventListener('blur', () => {
        if (disabled) {
            return;
        }

        if (textInput.value.trim() !== '') {
            addFromInput(textInput.value);
        }
    });

    render();
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initPillboxes(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initPillboxes());
    } else {
        initPillboxes();
    }
}
